  ["paladin-retribution.s4.opening2.if"] = "Command with a slow weapon, else Righteousness",
  ["paladin-retribution.s4.opening2.text"] = "A seal",
  ["paladin-retribution.s4.opening2.why"] = "a slow weapon gets more out of Command",
